$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$page = Decode ""

$pagePath = Join-Path $root "app\scores\page.tsx"
$scorePath = Join-Path $root "lib\provider-score.ts"
$apiPath = Join-Path $root "app\api\scores\recalculate\route.ts"

foreach ($path in @($pagePath, $scorePath, $apiPath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "13.01 : fichier requis introuvable : $path"
    }
}

$score = [System.IO.File]::ReadAllText($scorePath)
$api = [System.IO.File]::ReadAllText($apiPath)

if (-not $score.Contains("KLYX_GROUP_AWARE_PROVIDER_SCORE_13_00")) {
    throw "13.01 : KLYX Score group-aware 13.00 introuvable."
}

if (-not $score.Contains("completedSlots") -or -not $score.Contains("groupedMissionCount")) {
    throw "13.01 : metriques 13.00 incompletes."
}

if (-not $api.Contains("recalculateProviderScores")) {
    throw "13.01 : API score introuvable."
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

Copy-Item -LiteralPath $pagePath -Destination ($pagePath + ".bak-13-01-" + $timestamp) -Force

[System.IO.File]::WriteAllText($pagePath, $page, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 13.01 APPLIQUE"
Write-Host "======================================"
Write-Host "KLYX Score v3 : UI"
Write-Host "Missions commerciales : VISIBLES"
Write-Host "Creneaux execution : VISIBLES"
Write-Host "Mission groupee = 1 : EXPLIQUE"
Write-Host "Volume N slots : EXPLIQUE"
Write-Host "Paiement : INCHANGE"
Write-Host "======================================"
